# Check for triangles in the given edges
edges = [(1,16), (5,15), (4,13), (2,7), (6,13), (8,9), (2,6), (8,15), (5,6), (7,15), (2,5), (3,12), (1,11), (9,14), (4,7), (12,16), (4,16), (1,9), (7,11), (6,11), (13,14), (3,16), (10,12), (12,13), (0,12), (1,3), (0,14)]

# Build adjacency set
adj = {}
for u, v in edges:
    if u not in adj:
        adj[u] = set()
    if v not in adj:
        adj[v] = set()
    adj[u].add(v)
    adj[v].add(u)

# Check for triangles
triangles = []
for u in adj:
    for v in adj[u]:
        if v > u:
            for w in adj[u]:
                if w > v and w in adj[v]:
                    triangles.append((u, v, w))

print("Triangles found:", triangles)
print("Number of triangles:", len(triangles))

# If there are triangles, girth is 3
if triangles:
    print("Girth is 3 (triangles exist)")
else:
    print("No triangles found, checking for girth >= 4")
